<template><div class="biz-page"><PageHeader eyebrow="数据中心 · 闭店结转" title="每日营业结转" description="系统每日闭店后自动生成报告，也可补生成历史营业日"><el-button type="primary" :loading="generating" @click="generate">补生成日结</el-button></PageHeader><section class="biz-card toolbar"><el-date-picker v-model="date" value-format="YYYY-MM-DD" :disabled-date="disableUnclosedDate"/><el-button :loading="loading" @click="load">查询报告</el-button></section><template v-if="data"><section class="biz-stats"><StatCard label="销售实收" :value="formatMoney(data.totalSales)" :icon="Money"/><StatCard label="退款金额" :value="formatMoney(data.refundAmount)" :icon="Money" tone="orange"/><StatCard label="净销售额" :value="formatMoney(data.netSales)" :icon="Money"/><StatCard label="订单数" :value="data.orderCount" :icon="Tickets"/><StatCard label="优惠让利" :value="formatMoney(totalDiscount)" :icon="Discount" tone="orange"/><StatCard label="消耗积分" :value="data.pointConsumed" :icon="Coin" tone="purple"/></section><section class="biz-card"><el-descriptions :column="3" border><el-descriptions-item label="限时特价让利">{{ formatMoney(data.promotionDiscount) }}</el-descriptions-item><el-descriptions-item label="会员折扣让利">{{ formatMoney(data.memberDiscount) }}</el-descriptions-item><el-descriptions-item label="优惠券核销">{{ formatMoney(data.couponDeduct) }}</el-descriptions-item><el-descriptions-item label="积分抵扣金额">{{ formatMoney(data.pointDeduct) }}</el-descriptions-item><el-descriptions-item label="状态">{{ data.status }}</el-descriptions-item><el-descriptions-item label="生成时间">{{ formatDateTime(data.createTime) }}</el-descriptions-item></el-descriptions></section></template><el-empty v-else-if="!loading" description="请选择已闭店日期查询或补生成日结报告"/></div></template>
<script setup lang="ts">import{computed,ref}from'vue';import{Coin,Discount,Money,Tickets}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import PageHeader from'../../components/PageHeader.vue';import StatCard from'../../components/StatCard.vue';import{statisticsApi}from'../../api/statistics';import type{DailySettlement}from'../../types/statistics';import{formatDateTime,formatMoney}from'../../utils/format';const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const toLocalDate=(value:Date)=>value.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});const date=ref(toLocalDate(yesterday)),data=ref<DailySettlement|null>(null),loading=ref(false),generating=ref(false);const totalDiscount=computed(()=>Number(data.value?.promotionDiscount||0)+Number(data.value?.memberDiscount||0)+Number(data.value?.couponDeduct||0)+Number(data.value?.pointDeduct||0));const disableUnclosedDate=(value:Date)=>toLocalDate(value)>=toLocalDate(new Date());async function load(){loading.value=true;try{data.value=await statisticsApi.getDailySettlement(date.value)}catch{data.value=null}finally{loading.value=false}}async function generate(){generating.value=true;try{data.value=await statisticsApi.generateDailySettlement(date.value);ElMessage.success('日结报告已生成')}finally{generating.value=false}}</script><style scoped>.toolbar{margin-bottom:14px;display:flex;gap:10px}</style>
